package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    in attribute io_1 : Boolean;
    attribute counter : Integer := 0;
    attribute prevIncPressed : Boolean := false;
    attribute prevDecPressed : Boolean := false;
    perform action tick {
      first start;
      then if ((io_0) and ((not prevIncPressed))) {
        first start;
        then assign counter := (if ((counter) >= (20)) ? 20 else counter + 1);
      }
      then if ((io_1) and ((not prevDecPressed))) {
        first start;
        then assign counter := (if ((counter) <= (0)) ? 0 else counter - 1);
      }
      then assign prevIncPressed := io_0;
      then assign prevDecPressed := io_1;
    }
    out attribute io_2 : Integer = (if ((((counter) == (20))) or (((counter) == (0)))) ? 1000 else 0);
    out attribute io_3 : Integer = counter;
  }
  part system : Controller;
}
